// План specs/payments-portal.md 1.1 / 1.2 (#a83f47). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Только чтение (@prod-safe).
// 1.1 — View Details открывает окно «Payment details»: сумма, статус, дата, клиент, способ оплаты; Close закрывает, остаёмся в портале.
// 1.2 — у возвращённого платежа (JOB-0002, $2): Status Refunded + Amount refunded, ссылка на работу JOB-0002.
// Источник: «מה רצוי» тикета — окно с суммой, датой, клиентом, работой/счётом, способом оплаты, статусом (включая Refunded).
// Факты 17.11 (app + web): окно Payment details; у Refunded — статус и сумма возврата. Без пометки устройства — десктоп + телефоны.
import { test, expect } from '../../fixtures';
import { ROLE, detailsDialog, openPortal, txRows } from './portal-helpers';

test.describe('Payment Portal — View Details (#a83f47)', () => {
  test('View Details opens the "Payment details" window with amount, status, date, customer, payment method; Close keeps the portal #a83f47 @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await openPortal(page);
    await txRows(page).first().getByRole('button', { name: 'View Details' }).click();

    const dialog = detailsDialog(page);
    await expect(dialog).toBeVisible();
    for (const label of ['Amount', 'Status', 'Date', 'Customer', 'Payment method']) {
      await expect(dialog.getByText(label, { exact: true }), `в окне поле «${label}»`).toBeVisible();
    }
    await expect(dialog.getByText(/\$\d/).first()).toBeVisible();

    await dialog.getByRole('button', { name: 'Close', exact: true }).click();
    await expect(dialog).toBeHidden();
    await expect(page, 'остались на портале').toHaveURL(/\/Payments/i);
  });

  test('Refunded payment: window shows Status Refunded, Amount refunded and the JOB link #a83f47 @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await openPortal(page);
    const refunded = txRows(page).filter({ hasText: 'Refunded' }).first();
    await expect(refunded, 'в портале есть возвращённый платёж (JOB-0002, $2)').toBeVisible();
    await refunded.getByRole('button', { name: 'View Details' }).click();

    const dialog = detailsDialog(page);
    await expect(dialog).toBeVisible();
    await expect(dialog.getByText('Refunded', { exact: true })).toBeVisible();
    await expect(dialog.getByText('Amount refunded', { exact: true })).toBeVisible();
    await expect(dialog.getByRole('link', { name: /^JOB-\d{4}/ })).toBeVisible();
  });
});
